import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

public class PoolDemo {
    public static void main(String[] args) {
        AtomicInteger seq = new AtomicInteger();
        ThreadPoolExecutor pool = new ThreadPoolExecutor(
                4, 8, 60, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(200),                 // 有界队列，防 OOM
                r -> new Thread(r, "order-pool-" + seq.incrementAndGet()),
                new ThreadPoolExecutor.CallerRunsPolicy());    // 满了让调用方降速
        for (int i = 0; i < 10; i++) {
            int n = i;
            pool.execute(() -> System.out.println(Thread.currentThread().getName() + " -> " + n));
        }
        pool.shutdown();
    }
}

import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.*;

public class LockDemo {
    private final ReentrantLock lock = new ReentrantLock();      // 非公平
    private final Condition notEmpty = lock.newCondition();
    private int stock = 0;

    public boolean tryDeduct() throws InterruptedException {
        if (!lock.tryLock(200, TimeUnit.MILLISECONDS)) return false; // 超时放弃
        try {
            while (stock == 0) notEmpty.await();
            stock--;
            return true;
        } finally {
            lock.unlock();                                       // 必须在 finally
        }
    }

    public synchronized void simpleAdd() { stock++; }            // 异常时自动释放
}

import java.util.concurrent.locks.AbstractQueuedSynchronizer;

/** 一个不可重入的互斥锁，演示 AQS 模板方法 */
public class SimpleMutex {
    private static class Sync extends AbstractQueuedSynchronizer {
        @Override protected boolean tryAcquire(int arg) {
            if (compareAndSetState(0, 1)) {
                setExclusiveOwnerThread(Thread.currentThread());
                return true;
            }
            return false;
        }
        @Override protected boolean tryRelease(int arg) {
            if (getState() == 0) throw new IllegalMonitorStateException();
            setExclusiveOwnerThread(null);
            setState(0);
            return true;
        }
    }
    private final Sync sync = new Sync();
    public void lock()   { sync.acquire(1); }
    public void unlock() { sync.release(1); }
}

public final class UserContext {
    private static final ThreadLocal<Long> USER_ID = new ThreadLocal<>();
    public static void set(Long id) { USER_ID.set(id); }
    public static Long get()        { return USER_ID.get(); }
    public static void clear()      { USER_ID.remove(); }
