// Spring MVC 拦截器中使用
@Component
public class UserInterceptor implements HandlerInterceptor {
    @Override
    public boolean preHandle(HttpServletRequest req, HttpServletResponse resp, Object h) {
        UserContext.set(Long.valueOf(req.getHeader("X-User-Id")));
        return true;
    }
    @Override
    public void afterCompletion(HttpServletRequest req, HttpServletResponse resp, Object h, Exception ex) {
        UserContext.clear();   // 线程池复用，必须清理
    }
}

import java.util.concurrent.atomic.*;

public class CasDemo {
    public static void main(String[] args) {
        AtomicInteger cnt = new AtomicInteger();
        cnt.incrementAndGet();                         // 内部 CAS 自旋

        // 带版本号，解决 ABA
        AtomicStampedReference<Integer> ref = new AtomicStampedReference<>(100, 0);
        int stamp = ref.getStamp();
        boolean ok = ref.compareAndSet(100, 80, stamp, stamp + 1);
        System.out.println(ok + " stamp=" + ref.getStamp());   // true stamp=1
        // 旧版本号再次 CAS 会失败
        System.out.println(ref.compareAndSet(80, 50, stamp, stamp + 1)); // false

        LongAdder pv = new LongAdder();                // 高并发计数优于 AtomicLong
        pv.increment();
        System.out.println(pv.sum());
    }
}

import java.util.concurrent.*;
import java.util.stream.IntStream;

public class VtDemo {
    public static void main(String[] args) throws Exception {
        Semaphore limit = new Semaphore(50);                     // 限制对下游的并发，而不是池化
        try (ExecutorService es = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, 10_000).forEach(i -> es.submit(() -> {
                limit.acquire();
                try {
                    Thread.sleep(1000);                          // 模拟调用 LLM/HTTP，会卸载不占载体线程
                } finally {
                    limit.release();
                }
                return i;
            }));
        }   // try-with-resources 会等待所有任务结束
        Thread vt = Thread.ofVirtual().name("vt-1").start(() -> System.out.println("hello"));
        vt.join();
    }
}
