public class StateDemo {
    public static void main(String[] args) throws Exception {
        Object lock = new Object();
        Thread t = new Thread(() -> {
            synchronized (lock) {
                try { lock.wait(); } catch (InterruptedException ignored) {}
            }
        });
        System.out.println(t.getState());   // NEW
        t.start();
        Thread.sleep(100);
        System.out.println(t.getState());   // WAITING（在 lock.wait()）
        synchronized (lock) {
            lock.notify();
            Thread.sleep(100);
            System.out.println(t.getState()); // BLOCKED（被唤醒但主线程仍持有锁）
        }
        t.join();
        System.out.println(t.getState());   // TERMINATED
    }
}

int cores = Runtime.getRuntime().availableProcessors();

// CPU 密集
ThreadPoolExecutor cpuPool = new ThreadPoolExecutor(cores + 1, cores + 1, 0, TimeUnit.SECONDS,
        new ArrayBlockingQueue<>(100), new ThreadPoolExecutor.CallerRunsPolicy());

// IO 密集：8 核，等待/计算 = 9，目标利用率 0.8 → 约 64
int ioThreads = (int) (cores * 0.8 * (1 + 9));
ThreadPoolExecutor ioPool = new ThreadPoolExecutor(ioThreads, ioThreads * 2, 60, TimeUnit.SECONDS,
        new ArrayBlockingQueue<>(500), r -> new Thread(r, "io-pool"),
        new ThreadPoolExecutor.AbortPolicy());

// 运行时可调整（配合配置中心实现动态线程池）
ioPool.setCorePoolSize(80);
ioPool.setMaximumPoolSize(120);

// 监控
log.info("active={} queue={} completed={}", ioPool.getActiveCount(),
        ioPool.getQueue().size(), ioPool.getCompletedTaskCount());
